def calculate_average_annual_growth_rate(population_data):
    growth_rates = {}
    for species, populations in population_data.items():
        if len(populations) < 2:
            continue  # Skip species with less than two data points
        initial_population = populations[next(iter(populations))]
        for year in sorted(populations.keys()):
            final_population = populations[year]
            annual_growth_rate = ((final_population - initial_population) / initial_population) * 100
            growth_rates.setdefault(species, []).append(annual_growth_rate)
    for species, rates in growth_rates.items():
        average_growth_rate = sum(rates) / len(rates)
        growth_rates[species] = average_growth_rate
    return growth_rates

