def calculate_vowel_frequency_and_rank(language_data):
    # First, calculate the frequency of each vowel across all languages
    total_frequencies = {}
    for language, vowels in language_data.items():
        total_vowels = sum(vowels.values())
        for vowel, count in vowels.items():
