from datetime import datetime

def calculate_recovery_times(treatment_data, start_date, end_date):
    # Assumes treatment_data is a dictionary { "Treatment": [recovery times], ... }
    averages = {}
    improvements = {}

    for treatment, times in treatment_data.items():
        if not times:
            continue

        dates = [datetime.strptime(d, "%Y-%m-%d") for d in treatment_data[treatment]]
        if any(date < start_date or date > end_date for date in dates):
            continue

        average = sum(times) / len(times)
        averages[treatment] = average

        if start_date and end_date:
            earliest_date = min(dates)
            latest_date = max(dates)
            improvement = (earliest_date - latest_date).days / (latest_date - start_date).days * 100
            improvements[treatment] = improvement

