def calculate_population_growth(species_data):
    # species_data is a dictionary { 'Species': [population1, population2, population3], ... }
    growth_rates = {}
    for species, populations in species_data.items():
        growth = (populations[-1] - populations[0]) / populations[0]
        growth_rates[species] = growth
    return growth_rates


